import {runProject,CATEGORIES} from './engine.js?v=1.9.0';
export const SENSITIVITY_PARAMETERS={vgsOn:'Gate-on Vgs',rgOn:'Turn-on gate resistance',rgOff:'Turn-off gate resistance',temperature:'Reference temperature',parallel:'Parallel device count',frequency:'Waveform frequency'};
export function sensitivityScenario(project,config,parameter,direction){const p=structuredClone(project),inst=p.instances.find(i=>i.id===config.instanceId),c=inst?.candidates.find(c=>c.id===config.candidateId);if(!c)throw Error('Select a candidate in the chosen combination');const percent=Number(config.percent??2);if(!(percent>0&&percent<50))throw Error('Sensitivity percentage must be between 0 and 50');let before,after,unit='%',change;
 if(parameter==='frequency'){before=1;after=1+direction*percent/100;for(const w of p.waveforms)w.columns[w.time]=w.columns[w.time].map(t=>t/after);p.operating.window/=after;for(const i of p.instances)for(const candidate of i.candidates)if(candidate.coreFrequency>0)candidate.coreFrequency*=after;change=direction*percent;}
 else if(parameter==='temperature'){before=c.thermal.temperature;const step=Number(config.temperatureStep??5);if(!(step>0&&Number.isFinite(step)))throw Error('Temperature step must be positive');after=before+direction*step;c.thermal.temperature=after;unit='°C';change=direction*step;}
 else if(parameter==='parallel'){before=c.parallel;after=before+direction;if(after<1)throw Error('Parallel count cannot fall below one');c.parallel=after;c.totalCount=c.totalCount*after/before;if(!Number.isInteger(c.totalCount))throw Error('Replicated device count cannot be rescaled to an integer');change=100*(after/before-1);}
 else{if(parameter==='vgsOn'&&c.gateType!=='logic')throw Error('Gate-on Vgs sensitivity requires a logic gate waveform');before=c[parameter];if(!(Number.isFinite(before)&&before>0))throw Error('Baseline parameter must be positive');after=before*(1+direction*percent/100);c[parameter]=after;change=direction*percent;}
 return {project:p,before,after,change,unit};}
function metrics(result){if(!result.rows.length||result.rows.some(r=>!r.valid))return null;const count=result.rows.length;return {loss:result.rows.reduce((s,r)=>s+r.totalLoss,0)/count,efficiency:result.rows.reduce((s,r)=>s+r.efficiency,0)/count,categories:Object.fromEntries(CATEGORIES.map(k=>[k,result.rows.reduce((s,r)=>s+r.categories[k],0)/count]))};}
export function runSensitivity(project,config,progress=()=>{}){const p=structuredClone(project);for(const i of p.instances){const id=config.selection[i.id];i.candidates=i.candidates.filter(c=>c.id===id);if(!i.candidates.length)throw Error('Selected combination is no longer available');}if(config.waveformId)p.waveforms=p.waveforms.filter(w=>w.id===config.waveformId);const baseline=runProject(p),base=metrics(baseline);if(!base)throw Error('Sensitivity requires a complete valid baseline');const parameters=config.parameters||['vgsOn'],scenarios=[],total=parameters.length*2;let done=0;
 for(const parameter of parameters){if(!(parameter in SENSITIVITY_PARAMETERS))throw Error('Unknown sensitivity parameter');for(const direction of [-1,1]){try{const changed=sensitivityScenario(p,config,parameter,direction),result=runProject(changed.project),m=metrics(result),warnings=[...new Set(result.rows.flatMap(r=>r.devices.flatMap(d=>d.notes||[d.error])).filter(Boolean))];scenarios.push({parameter,label:SENSITIVITY_PARAMETERS[parameter],direction,before:changed.before,after:changed.after,change:changed.change,unit:changed.unit,valid:!!m,meanLoss:m?.loss??null,lossChange:m&&base.loss!==0?100*(m.loss/base.loss-1):null,lossDelta:m?m.loss-base.loss:null,efficiencyDelta:m?m.efficiency-base.efficiency:null,elasticity:m&&base.loss!==0&&changed.unit==='%'&&changed.change!==0?(100*(m.loss/base.loss-1))/changed.change:null,categories:m?.categories,points:result.rows.map(r=>({waveformId:r.waveformId,vin:r.vin,vout:r.vout,outputPower:r.outputPower,valid:r.valid,totalLoss:r.totalLoss,baselineLoss:baseline.rows.find(b=>b.waveformId===r.waveformId)?.totalLoss})),warnings,errors:result.rows.flatMap(r=>r.reasons||[])});}catch(e){scenarios.push({parameter,label:SENSITIVITY_PARAMETERS[parameter],direction,valid:false,errors:[e.message]});}progress(++done/total);}}
 return {baseline:base,scenarios,instanceId:config.instanceId,candidateId:config.candidateId,combination:config.combination,operatingPoints:baseline.rows.length,createdAt:new Date().toISOString(),assumption:'One parameter at a time. Imported waveforms held fixed except the frequency scenario, which rescales time while retaining waveform shape. These are model sensitivities, not a circuit re-simulation. Unrepresented dependencies can give zero sensitivity; extrapolation warnings must be reviewed.'};}
